window.HSCI202_DATA={"course":"HSci 202","title":"Neuroanatomy","mcq_sets":[{"id":"compiled-part-1","group":"Compiled MCQs","section":"Part I","title":"Neuron Function & Glia","faculty":"Dr. Labarda","subtitle":"Dr. Labarda • 5 source-keyed MCQs","source":"HSci202_Compiled_MCQs_with_Rationale.pdf","questions":[{"id":"compiled-part-1-1","set_id":"compiled-part-1","type":"mcq","source_number":"1","source_page":1,"prompt":"Which of the following analogies best describes the functional relationship between two different parts of a neuron?","options":[{"label":"A","text":"A cell body is to synaptic output, as an axon is to action potential conduction."},{"label":"B","text":"A cell body is to a dendrite, as synaptic output is to synaptic integration."},{"label":"C","text":"A dendrite is to an axon terminal, as postsynaptic input is to presynaptic output."},{"label":"D","text":"A dendrite is to neurotransmitter release, as an axon terminal is to postsynaptic membrane neurotransmitter receptors."}],"answer":"C","rationale":"A dendrite receives incoming signals (postsynaptic input), while an axon terminal sends signals to the next neuron (presynaptic output). Thus, the analogy matches input (dendrite) and output (axon terminal) functions. Other choices confuse structures with processes or reverse directions of signaling.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-1-2","set_id":"compiled-part-1","type":"mcq","source_number":"2","source_page":1,"prompt":"A 74-year-old man had a sudden blockage of an artery that supplied a portion of the white matter in the pons. Which of the following neuron components is located within a white matter tract?","options":[{"label":"A","text":"Axon"},{"label":"B","text":"Cell body"},{"label":"C","text":"Axon termination"},{"label":"D","text":"Dendrite"}],"answer":"A","rationale":"White matter is composed of myelinated axons that transmit signals between different CNS areas. Gray matter contains neuron cell bodies, dendrites, and synapses. Hence, an axon is the correct answer.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-1-3","set_id":"compiled-part-1","type":"mcq","source_number":"3","source_page":1,"prompt":"Which of the following best lists the parts of neurons that are located in a nucleus?","options":[{"label":"A","text":"Cell bodies, dendrites, axons, and axon terminals"},{"label":"B","text":"Cell bodies and dendrites"},{"label":"C","text":"Cell bodies, axons, and dendrites"},{"label":"D","text":"Cell bodies only"}],"answer":"B","rationale":"In the CNS, a nucleus refers to a cluster of neuron cell bodies (gray matter). Dendrites may also be present within this region to receive inputs. Axons usually project out to other areas and are part of white matter tracts.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-1-4","set_id":"compiled-part-1","type":"mcq","source_number":"4","source_page":2,"prompt":"Which of the following analogies best describes the function of Schwann cells and oligodendrocytes?","options":[{"label":"A","text":"The myelin sheath of central nervous system axons is to the myelin sheath of peripheral nervous system axons."},{"label":"B","text":"The myelin sheath of peripheral nervous system axons is to the myelin sheath of central nervous system axons."},{"label":"C","text":"Central nervous system action potential conduction is to peripheral nervous system action potential conduction."},{"label":"D","text":"Peripheral nervous system axon structure is to central nervous system axon structure."}],"answer":"B","rationale":"Schwann cells myelinate axons in the PNS, while oligodendrocytes myelinate axons in the CNS. The correct analogy compares the corresponding myelinating cells and their respective locations.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-1-5","set_id":"compiled-part-1","type":"mcq","source_number":"5","source_page":2,"prompt":"A person suffers from a traumatic brain injury. There is bleeding and inflammation at the injury site. Which of the following cell types plays a phagocytic role in eliminating blood and tissue debris?","options":[{"label":"A","text":"Schwann cells"},{"label":"B","text":"Neurons"},{"label":"C","text":"Microglia"},{"label":"D","text":"Astrocytes"}],"answer":"C","rationale":"Microglia are the resident macrophages of the CNS. They act as immune defense cells and remove cellular debris and pathogens through phagocytosis. Astrocytes maintain the blood-brain barrier and ionic balance, not immune cleanup.","key_status":"source","key_source":"Compiled HS202 MCQs"}]},{"id":"compiled-part-2","group":"Compiled MCQs","section":"Part II","title":"Neurohistology, Development & Nerve Injury","faculty":"Dr. Labarda","subtitle":"Dr. Labarda • 10 source-keyed MCQs","source":"HSci202_Compiled_MCQs_with_Rationale.pdf","questions":[{"id":"compiled-part-2-1","set_id":"compiled-part-2","type":"mcq","source_number":"1","source_page":2,"prompt":"The “Nissl substance” represents which organelle of the neuron?","options":[{"label":"A","text":"Golgi complex"},{"label":"B","text":"Nucleolus"},{"label":"C","text":"Rough endoplasmic reticulum"},{"label":"D","text":"Mitochondria"}],"answer":"C","rationale":"Nissl bodies are clumps of rough endoplasmic reticulum and ribosomes found in neuron cell bodies and dendrites. They are responsible for protein synthesis essential for neuronal function and repair.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-2","set_id":"compiled-part-2","type":"mcq","source_number":"2","source_page":3,"prompt":"Which of the following provides myelin sheath to the axons of the CNS?","options":[{"label":"A","text":"Astrocytes"},{"label":"B","text":"Oligodendrocytes"},{"label":"C","text":"Microglia"},{"label":"D","text":"Ependymocytes"}],"answer":"B","rationale":"Oligodendrocytes form myelin sheaths around CNS axons, increasing conduction speed. Each oligodendrocyte can myelinate several axons. In contrast, Schwann cells (not listed here) myelinate PNS axons.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-3","set_id":"compiled-part-2","type":"mcq","source_number":"3","source_page":3,"prompt":"The perivascular foot of the “blood–brain barrier” is an extension from the:","options":[{"label":"A","text":"Oligodendrocyte"},{"label":"B","text":"Ependymocyte"},{"label":"C","text":"Astrocyte"},{"label":"D","text":"Microglia"}],"answer":"C","rationale":"Astrocytic end-feet surround CNS capillaries to help form the blood–brain barrier (BBB), regulating the movement of substances between the blood and neural tissue.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-4","set_id":"compiled-part-2","type":"mcq","source_number":"4","source_page":3,"prompt":"Sensation of pain is detected by:","options":[{"label":"A","text":"Mechanoreceptor"},{"label":"B","text":"Chemoreceptor"},{"label":"C","text":"Nociceptor"},{"label":"D","text":"Thermoreceptor"}],"answer":"C","rationale":"Nociceptors are specialized sensory receptors that detect painful stimuli, including tissue damage. Mechanoreceptors detect pressure/touch, chemoreceptors detect chemical stimuli, and thermoreceptors detect temperature.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-5","set_id":"compiled-part-2","type":"mcq","source_number":"5","source_page":3,"prompt":"The cerebral aqueduct is developed from the cavity of:","options":[{"label":"A","text":"Rhombencephalon"},{"label":"B","text":"Mesencephalon"},{"label":"C","text":"Telencephalon"},{"label":"D","text":"Diencephalon"}],"answer":"B","rationale":"The cerebral aqueduct (of Sylvius) connects the third and fourth ventricles and arises from the mesencephalon (midbrain) during embryologic development.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-6","set_id":"compiled-part-2","type":"mcq","source_number":"6","source_page":4,"prompt":"The failure of closure of the cranial end of the neural tube gives rise to:","options":[{"label":"A","text":"Anencephaly"},{"label":"B","text":"Hydrocephalus"},{"label":"C","text":"Microcephaly"},{"label":"D","text":"Meningomyelocoele"}],"answer":"A","rationale":"Anencephaly results from failure of the rostral (cranial) neuropore to close, leading to absence of most of the brain and skull. Failure of the caudal end closure leads to spina bifida or meningomyelocele.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-7","set_id":"compiled-part-2","type":"mcq","source_number":"7","source_page":4,"prompt":"By which week of intrauterine life does the neural tube close?","options":[{"label":"A","text":"Fourth"},{"label":"B","text":"Fifth"},{"label":"C","text":"Sixth"},{"label":"D","text":"Seventh"}],"answer":"A","rationale":"The neural tube closes around the 4th week of embryonic development, beginning in the cervical region and proceeding both cranially and caudally.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-8","set_id":"compiled-part-2","type":"mcq","source_number":"8","source_page":4,"prompt":"The cervical flexure of the neural tube occurs:","options":[{"label":"A","text":"Between the forebrain and midbrain"},{"label":"B","text":"In the midbrain"},{"label":"C","text":"Between hindbrain and spinal cord"},{"label":"D","text":"In the hindbrain"}],"answer":"C","rationale":"The cervical flexure marks the junction between the hindbrain (rhombencephalon) and the spinal cord during neural tube development.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-9","set_id":"compiled-part-2","type":"mcq","source_number":"9","source_page":4,"prompt":"During surgery on the parotid salivary gland, the auriculotemporal nerve got damaged. When recovery occurred, the secretomotor fibres of the auriculotemporal nerve got exchanged with the sympathetic fibres supplying the sweat glands of the skin over the parotid gland. What is the type of nerve injury to the auriculotemporal nerve in this patient?","options":[{"label":"A","text":"Neurotmesis"},{"label":"B","text":"Neurapraxia"},{"label":"C","text":"Axonotmesis"},{"label":"D","text":"All of the above"}],"answer":"C","rationale":"Axonotmesis involves damage to the axon and myelin sheath but preservation of the connective tissue framework. It allows aberrant regeneration, such as misdirected nerve fibers, explaining gustatory sweating (Frey’s syndrome).","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-2-10","set_id":"compiled-part-2","type":"mcq","source_number":"10","source_page":5,"prompt":"In what type of nerve injury will the auriculotemporal nerve recover completely?","options":[{"label":"A","text":"Neurotmesis"},{"label":"B","text":"Neurapraxia"},{"label":"C","text":"Axonotmesis"},{"label":"D","text":"B and C"}],"answer":"B","rationale":"Neurapraxia is the mildest form of nerve injury, where conduction is blocked but the axon and connective tissues remain intact. Full recovery occurs within weeks. Axonotmesis can recover partially but may lead to misdirected regeneration.","key_status":"source","key_source":"Compiled HS202 MCQs"}]},{"id":"compiled-part-3","group":"Compiled MCQs","section":"Part III","title":"Cranial Nerve Examination","faculty":"Doc Hannah","subtitle":"Doc Hannah • 8 source-keyed MCQs","source":"HSci202_Compiled_MCQs_with_Rationale.pdf","questions":[{"id":"compiled-part-3-1","set_id":"compiled-part-3","type":"mcq","source_number":"1","source_page":5,"prompt":"A 68-year-old man presents with dysarthria and dysphagia. On exam, his tongue is small and tight but shows no fasciculations. The gag reflex is brisk, and he occasionally bursts into inappropriate laughter. Which of the following best describes his condition?","options":[{"label":"A","text":"Bilateral LMN lesion of CN IX-XII (bulbar palsy)"},{"label":"B","text":"Bilateral UMN corticobulbar lesion (pseudobulbar palsy)"},{"label":"C","text":"Unilateral LMN lesion of CN XII"},{"label":"D","text":"Unilateral UMN lesion of CN VII"}],"answer":"B","rationale":"The presence of brisk reflexes (hyperreflexia) and emotional lability (inappropriate laughter) points to an upper motor neuron lesion affecting bilateral corticobulbar tracts — characteristic of pseudobulbar palsy.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-2","set_id":"compiled-part-3","type":"mcq","source_number":"2","source_page":5,"prompt":"When asked to protrude the tongue, it deviates to the right side. The tongue is wasted and presents with fasciculation on that side. Which statement is correct?","options":[{"label":"A","text":"Right UMN lesion"},{"label":"B","text":"Left UMN lesion"},{"label":"C","text":"Right LMN lesion"},{"label":"D","text":"Left LMN lesion"}],"answer":"C","rationale":"Fasciculations and atrophy indicate lower motor neuron (LMN) damage. The tongue deviates toward the affected side because of unopposed action of the contralateral genioglossus muscle.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-3","set_id":"compiled-part-3","type":"mcq","source_number":"3","source_page":6,"prompt":"A patient's Weber test lateralizes to the right, and Rinne test shows BC > AC on the right, AC > BC on the left. Which is the most likely diagnosis?","options":[{"label":"A","text":"Right conductive hearing loss"},{"label":"B","text":"Left conductive hearing loss"},{"label":"C","text":"Right sensorineural hearing loss"},{"label":"D","text":"Left sensorineural hearing loss"}],"answer":"A","rationale":"In conductive hearing loss, the Weber test lateralizes to the affected ear, and Rinne test shows bone conduction > air conduction on that side.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-4","set_id":"compiled-part-3","type":"mcq","source_number":"4","source_page":6,"prompt":"A patient standing 6 m from a Snellen chart can only read letters normally legible at 60 m. How should you record this visual acuity?","options":[{"label":"A","text":"6/6"},{"label":"B","text":"6/12"},{"label":"C","text":"6/36"},{"label":"D","text":"6/60"}],"answer":"D","rationale":"Visual acuity is expressed as (distance tested)/(distance a normal eye can read). If the patient reads at 6 m what a normal person reads at 60 m, vision is 6/60.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-5","set_id":"compiled-part-3","type":"mcq","source_number":"5","source_page":6,"prompt":"A 55-year-old woman reports numbness of her right face. On PE: Pinprick is lost over the right forehead, cheek, and chin. Corneal reflex is absent when the right cornea is touched, but intact when the left is tested. Jaw movement is strong and symmetric. Where is the lesion most likely located?","options":[{"label":"A","text":"Right motor root of CN V"},{"label":"B","text":"Right trigeminal (Gasserian) ganglion"},{"label":"C","text":"Left sensory nucleus of CN V in the pons"},{"label":"D","text":"Right mandibular branch (V3) only"}],"answer":"B","rationale":"Involvement of all three sensory divisions (V1–V3) with preserved motor function localizes the lesion before the division of the trigeminal nerve — at the Gasserian ganglion.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-6","set_id":"compiled-part-3","type":"mcq","source_number":"6","source_page":6,"prompt":"A patient cannot close the left eye, raise the left eyebrow, or smile on the left side. He also complains of hyperacusis and loss of taste on the anterior two-thirds of the tongue. Where is the lesion most likely located?","options":[{"label":"A","text":"Left motor cortex (UMN)"},{"label":"B","text":"Left facial nerve within the facial canal proximal to the chorda tympani branch"},{"label":"C","text":"Left facial nerve after the stylomastoid foramen"},{"label":"D","text":"Right internal capsule"}],"answer":"B","rationale":"The presence of hyperacusis (stapedius nerve involvement) and loss of taste (chorda tympani involvement) indicates that the lesion is proximal to the chorda tympani — inside the facial canal.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-7","set_id":"compiled-part-3","type":"mcq","source_number":"7","source_page":7,"prompt":"During confrontation testing, you cover your right eye while the patient covers the left. When you move your fingers in the upper and lower temporal fields of each eye, the patient fails to see them. All other fields are intact. Which lesion best explains this finding?","options":[{"label":"A","text":"Right optic nerve"},{"label":"B","text":"Optic chiasm"},{"label":"C","text":"Right optic tract"},{"label":"D","text":"Left occipital cortex"}],"answer":"B","rationale":"Loss of bilateral temporal visual fields (bitemporal hemianopia) results from compression of the optic chiasm, typically by a pituitary tumor.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-3-8","set_id":"compiled-part-3","type":"mcq","source_number":"8","source_page":7,"prompt":"A 62-year-old man with long-standing hypertension suddenly develops double vision and drooping of his right eyelid. On PE: Right eye – deviated downward and outward at rest. Right pupil – dilated and non-reactive to light. Left pupil – constricts normally. EOMs limited in upward, downward, and inward gaze in the right eye. Which of the following best describes the lesion and its typical cause?","options":[{"label":"A","text":"Right CN III palsy due to posterior communicating artery aneurysm"},{"label":"B","text":"Left CN VI palsy due to diabetic neuropathy"},{"label":"C","text":"Right optic nerve lesion due to ischemia"},{"label":"D","text":"Right Horner’s syndrome due to sympathetic chain compression"}],"answer":"A","rationale":"The triad of ptosis, \"down and out\" eye, and pupil dilation signifies a complete oculomotor (CN III) palsy. The most common compressive cause is a posterior communicating artery aneurysm.","key_status":"source","key_source":"Compiled HS202 MCQs"}]},{"id":"compiled-part-4","group":"Compiled MCQs","section":"Part IV","title":"Long Tracts & Pathways","faculty":"Dr. Jaya","subtitle":"Dr. Jaya • 10 source-keyed MCQs","source":"HSci202_Compiled_MCQs_with_Rationale.pdf","questions":[{"id":"compiled-part-4-1","set_id":"compiled-part-4","type":"mcq","source_number":"1","source_page":8,"prompt":"Which of the following is/are origin/s of the corticospinal tract?","options":[{"label":"A","text":"Precentral motor cortex"},{"label":"B","text":"Premotor area"},{"label":"C","text":"Medullary pyramid"},{"label":"D","text":"A & B"},{"label":"E","text":"All of the above"}],"answer":"D","rationale":"The corticospinal tract originates from the primary motor (precentral gyrus) and premotor areas of the cerebral cortex.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-2","set_id":"compiled-part-4","type":"mcq","source_number":"2","source_page":8,"prompt":"Fine touch, vibration, and proprioception are part of what long pathway?","options":[{"label":"A","text":"ALS"},{"label":"B","text":"DCML"},{"label":"C","text":"Corticospinal tract"},{"label":"D","text":"Spinothalamic tract"},{"label":"E","text":"Rubrospinal tract"}],"answer":"B","rationale":"The Dorsal Column–Medial Lemniscus (DCML) pathway carries fine touch, vibration, and proprioception.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-3","set_id":"compiled-part-4","type":"mcq","source_number":"3","source_page":8,"prompt":"What is the primary function of the descending pathways in the nervous system?","options":[{"label":"A","text":"To transmit motor commands from the brain and spinal cord to the muscles, therby controlling voluntary and involuntary movements."},{"label":"B","text":"To transmit motor commands from the brain and spinal cord to the muscles, thereby controlling voluntary movements."},{"label":"C","text":"To transmit sensory commands from the muscles to the brain and spinal cord, thereby controlling voluntary and involuntary movements."},{"label":"D","text":"To transmit sensory commands from the muscles to the brain and spinal cord, thereby controlling involuntary movements."},{"label":"E","text":"To transmit sensory commands from the muscles to the brain and spinal cord, thereby controlling voluntary movements."}],"answer":"A","rationale":"Descending tracts are motor pathways that deliver commands from the brain to effectors (muscles).","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-4","set_id":"compiled-part-4","type":"mcq","source_number":"4","source_page":9,"prompt":"Which of the following pathways in white matter is NOT a descending fiber system?","options":[{"label":"A","text":"Vestibulospinal tracts"},{"label":"B","text":"Rubrospinal tracts"},{"label":"C","text":"Reticulospinal system"},{"label":"D","text":"Spinothalamic tract"},{"label":"E","text":"Tectospinal tract"}],"answer":"D","rationale":"The spinothalamic tract is an ascending sensory pathway, not a descending motor one.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-5","set_id":"compiled-part-4","type":"mcq","source_number":"5","source_page":9,"prompt":"Which of the following regions of white matter would not contain corticospinal fibers?","options":[{"label":"A","text":"Pyramid of medulla oblongata"},{"label":"B","text":"Lateral white column of the spinal cord"},{"label":"C","text":"Cerebral peduncle of the midbrain"},{"label":"D","text":"Anterior limb of the internal capsule"},{"label":"E","text":"Corona radiata"}],"answer":"D","rationale":"Corticospinal fibers pass through the posterior limb, not the anterior limb, of the internal capsule.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-6","set_id":"compiled-part-4","type":"mcq","source_number":"6","source_page":9,"prompt":"Which of the following is true of the Descending Autonomic System?","options":[{"label":"A","text":"It modulates autonomic functions, such as blood pressure, pulse and respiratory rates, and sweating."},{"label":"B","text":"This fiber system arises in the contralateral red nucleus in the brain stem and courses in the lateral white column."},{"label":"C","text":"Fibers of the vestibulospinal tracts provide excitatory input to the LMNs for extensor muscles"},{"label":"D","text":"They provide synaptic input to LMNs controlling axial (i.e, trunk and proximal limb) musculature involved in maintaining body posture."},{"label":"E","text":"From the ventral posterolateral thalamic nuclei sensory information is relayed upward to the somatosensory cortex"}],"answer":"A","rationale":"This system controls visceral autonomic functions, regulating involuntary processes like heart rate and blood pressure.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-7","set_id":"compiled-part-4","type":"mcq","source_number":"7","source_page":9,"prompt":"Which of the following signs and symptoms below is indicative of syringomyelia?","options":[{"label":"A","text":"Dissociative anesthesia"},{"label":"B","text":"Babinski reflexes"},{"label":"C","text":"Hyperreflexia in the lower extremities"},{"label":"D","text":"Pain or tenderness on percussion over the vertebral column"},{"label":"E","text":"A sensory level"}],"answer":"A","rationale":"Syringomyelia causes a \"cape-like\" loss of pain and temperature (dissociative anesthesia) due to central cord involvement.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-8","set_id":"compiled-part-4","type":"mcq","source_number":"8","source_page":10,"prompt":"Which of the following disease conditions is characterized by damage to the dorsal roots and dorsal columns resulting in sensory ataxia?","options":[{"label":"A","text":"Tabes dorsalis"},{"label":"B","text":"Brown-Sequard syndrome"},{"label":"C","text":"Posterolateral sclerosis"},{"label":"D","text":"Spinal cord compression"},{"label":"E","text":"Syringomyelia"}],"answer":"A","rationale":"Tabes dorsalis, seen in neurosyphilis, affects dorsal roots and columns, leading to loss of proprioception and sensory ataxia.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-9","set_id":"compiled-part-4","type":"mcq","source_number":"9","source_page":10,"prompt":"Which of the following is true of the upper motor neuron?","options":[{"label":"A","text":"It is considered the final common pathway"},{"label":"B","text":"There are many neural impulses funnel through them to the muscle"},{"label":"C","text":"They are acted on by the corticospinal, rubrospinal, olivospinal, vestibulospinal, reticulospinal, and tectospinal tracts"},{"label":"D","text":"They are acted by intersegmental and intrasegmental reflex neurons"},{"label":"E","text":"Damage to the cerebral hemispheres or lateral white column of the spinal cord can produce signs of upper-motor-neuron lesions."}],"answer":"E","rationale":"UMN lesions produce spasticity, hyperreflexia, and Babinski sign due to loss of inhibitory cortical control.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-4-10","set_id":"compiled-part-4","type":"mcq","source_number":"10","source_page":10,"prompt":"Which of the following descending fiber systems coordinates eye and head movements?","options":[{"label":"A","text":"Medial Longitudinal Fasciculus"},{"label":"B","text":"Tectospinal tract"},{"label":"C","text":"Descending autonomic system"},{"label":"D","text":"Reticulospinal tract"},{"label":"E","text":"Vestibulospinal tract"}],"answer":"A","rationale":"The medial longitudinal fasciculus (MLF) links cranial nerves III, IV, and VI with neck muscles to coordinate eye-head movements.","key_status":"source","key_source":"Compiled HS202 MCQs"}]},{"id":"compiled-part-5","group":"Compiled MCQs","section":"Part V","title":"Brainstem, Cerebellum & Cranial Nerves","faculty":"Dr. Ade","subtitle":"Dr. Ade • 50 source-keyed MCQs","source":"HSci202_Compiled_MCQs_with_Rationale.pdf","questions":[{"id":"compiled-part-5-1","set_id":"compiled-part-5","type":"mcq","source_number":"1","source_page":12,"prompt":"JMR was admitted after the rally yesterday. Neurological examination reveals the following: Inability to shrug the right shoulder or turn the head to the left against resistance. A loss of pain and temperature sensation on the left side of the body. Normal muscle strength and coordination in all limbs. Based on these findings, which structure is most likely affected?","options":[{"label":"A","text":"Left Medulla Oblongata"},{"label":"B","text":"Right Medulla Oblongata"},{"label":"C","text":"Left Pons"},{"label":"D","text":"Right Midbrain"},{"label":"E","text":"Right Cerebellum"}],"answer":"B","rationale":"The lesion involves the right spinal accessory nucleus (in the medulla) and the contralateral spinothalamic tract, producing crossed findings. This pattern localizes to the right medulla.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-2","set_id":"compiled-part-5","type":"mcq","source_number":"2","source_page":12,"prompt":"KD presents with a right-sided intention tremor and past-pointing (dysmetria) on finger-to-nose testing. Imaging reveals a small ischemic stroke. Which vascular territory was most likely occluded?","options":[{"label":"A","text":"Left Posterior Inferior Cerebellar Artery (PICA)"},{"label":"B","text":"Right Superior Cerebellar Artery (SCA)"},{"label":"C","text":"Left Anterior Inferior Cerebellar Artery (AICA)"},{"label":"D","text":"Right Anterior Spinal Artery"},{"label":"E","text":"Left Pontine Perforating Artery"}],"answer":"B","rationale":"The SCA supplies the superior cerebellar hemisphere. Infarction causes ipsilateral cerebellar signs (intention tremor, dysmetria). PICA or AICA infarcts affect different regions of the cerebellum.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-3","set_id":"compiled-part-5","type":"mcq","source_number":"3","source_page":13,"prompt":"A lesion in the caudal pons is most likely to affect which of the following paired structures?","options":[{"label":"A","text":"Cerebral peduncles and Red nucleus"},{"label":"B","text":"Inferior olivary nuclei and Pyramids"},{"label":"C","text":"Middle cerebellar peduncles and Abducens nucleus (CN VI)"},{"label":"D","text":"Superior colliculi and Oculomotor nucleus (CN III)"},{"label":"E","text":"Gracile and Cuneate tubercles"}],"answer":"C","rationale":"The caudal pons houses the abducens nucleus (CN VI) and middle cerebellar peduncle. Lesions here produce horizontal gaze palsy and ataxia.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-4","set_id":"compiled-part-5","type":"mcq","source_number":"4","source_page":13,"prompt":"RD, 68, has a drooping left eyelid (ptosis), the left eye is turned down and out (\"down and out\"), and the left pupil is dilated. Which brainstem division and corresponding vascular territory is most likely involved?","options":[{"label":"A","text":"Medulla; Posterior Inferior Cerebellar Artery (PICA)"},{"label":"B","text":"Caudal Pons; Anterior Inferior Cerebellar Artery (AICA)"},{"label":"C","text":"Rostral Pons; Basilar Artery perforator"},{"label":"D","text":"Midbrain; Posterior Cerebral Artery (PCA)"},{"label":"E","text":"Cerebellum; Superior Cerebellar Artery (SCA)"}],"answer":"D","rationale":"Oculomotor nerve (CN III) emerges from the midbrain, supplied by the PCA. Lesions cause ipsilateral CN III palsy (ptosis, “down and out” eye, mydriasis).","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-5","set_id":"compiled-part-5","type":"mcq","source_number":"5","source_page":13,"prompt":"The loss of pain and temperature sensation on the left side of the face and the right side of the body is a classic \"crossed\" sensory finding that localizes to a lesion in the:","options":[{"label":"A","text":"Left lateral medulla"},{"label":"B","text":"Right lateral medulla"},{"label":"C","text":"Left lateral pons"},{"label":"D","text":"Right lateral pons"},{"label":"E","text":"Left midbrain"}],"answer":"A","rationale":"Loss of facial pain/temp on the same side and contralateral body pain/temp is classic for lateral medullary (Wallenberg) syndrome, usually due to PICA infarct.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-6","set_id":"compiled-part-5","type":"mcq","source_number":"6","source_page":14,"prompt":"BM, 65 y.o., presents with a right-sided lower motor neuron facial droop (forehead affected), a left-sided spastic hemiparesis, and a loss of pain and temperature sensation on the left side of the body. Which vessel is most likely to be occluded?","options":[{"label":"A","text":"Right Anterior Inferior Cerebellar Artery (AICA)"},{"label":"B","text":"Left Anterior Inferior Cerebellar Artery (AICA)"},{"label":"C","text":"Right Pontine Perforating Artery"},{"label":"D","text":"Left Pontine Perforating Artery"},{"label":"E","text":"Right Posterior Inferior Cerebellar Artery (PICA)"}],"answer":"A","rationale":"AICA stroke affects facial nucleus (CN VII) → LMN facial palsy; corticospinal tract → contralateral hemiparesis; and spinothalamic tract → contralateral pain/temp loss.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-7","set_id":"compiled-part-5","type":"mcq","source_number":"7","source_page":14,"prompt":"A stroke affecting the paramedian branches of the basilar artery at the level of the midbrain would likely damage all of the following structures EXCEPT:","options":[{"label":"A","text":"Corticospinal tract"},{"label":"B","text":"Corticobulbar tract"},{"label":"C","text":"Medial Lemniscus"},{"label":"D","text":"Oculomotor Nerve (CN III) fascicles"},{"label":"E","text":"Spinal Trigeminal Tract"}],"answer":"E","rationale":"A paramedian midbrain stroke (from basilar artery branches) damages corticospinal, corticobulbar, medial lemniscus, and CN III fascicles, but not the spinal trigeminal tract (which lies in the medulla and pons).","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-8","set_id":"compiled-part-5","type":"mcq","source_number":"8","source_page":14,"prompt":"A patient experiences sudden vertigo, nausea, nystagmus, and ataxia. Examination also reveals a loss of pain and temperature sensation on the right side of the face and the left side of the body. Which cranial nerve nucleus and major artery are implicated?","options":[{"label":"A","text":"Vestibular Nuclei; Anterior Inferior Cerebellar Artery (AICA)"},{"label":"B","text":"Abducens Nucleus (CN VI); Basilar Artery"},{"label":"C","text":"Spinal Trigeminal Nucleus (CN V); Posterior Inferior Cerebellar Artery (PICA)"},{"label":"D","text":"Facial Nucleus (CN VII); Pontine Perforating Artery"},{"label":"E","text":"Hypoglossal Nucleus (CN XII); Anterior Spinal Artery"}],"answer":"C","rationale":"Symptoms—vertigo, ataxia, ipsilateral facial pain/temp loss, contralateral body pain/temp loss—are classic for lateral medullary (Wallenberg) syndrome, caused by PICA infarct involving the spinal trigeminal nucleus.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-9","set_id":"compiled-part-5","type":"mcq","source_number":"9","source_page":15,"prompt":"Upon physical exam, a patient's right eye is adducted and depressed at rest (\"down and out\"). The right pupil's left eye abducts normally with nystagmus. This combination of findings is due to a single lesion affecting the:","options":[{"label":"A","text":"Right Medial Longitudinal Fasciculus (MLF) and Oculomotor Nerve (CN III) in the midbrain."},{"label":"B","text":"Left Abducens Nucleus (CN VI) and the Oculomotor Nerve (CN III) in the midbrain."},{"label":"C","text":"Right Oculomotor Nerve (CN III) and the Oculomotor Nerve (CN III) in the pons sinus."},{"label":"D","text":"Left Abducens Nucleus (CN VI) and the right Abducens Nucleus (CN VI) in the pons."},{"label":"E","text":"Right Medial Longitudinal Fasciculus (MLF) in the pons and the Oculomotor Nerve (CN III) in the midbrain."}],"answer":"A","rationale":"A lesion affecting both CN III and MLF produces internuclear ophthalmoplegia plus oculomotor palsy — the “one-and-a-half syndrome.”","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-10","set_id":"compiled-part-5","type":"mcq","source_number":"10","source_page":15,"prompt":"AR, a 62-year-old patient is admitted after the sudden onset of vertigo and vomiting. Examination reveals nystagmus, ataxia (gnosis, mostly). What is the most likely site of the lesion?","options":[{"label":"A","text":"Left medial medulla"},{"label":"B","text":"Right medial medulla"},{"label":"C","text":"Left lateral medulla"},{"label":"D","text":"Right lateral medulla"},{"label":"E","text":"Left lateral pons"}],"answer":"C","rationale":"Vertigo, vomiting, nystagmus, and ipsilateral ataxia → vestibular nuclei lesion; these are features of lateral medullary (PICA) infarct.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-11","set_id":"compiled-part-5","type":"mcq","source_number":"11","source_page":15,"prompt":"A patient presents with a right-sided lower motor neuron facial palsy (forehead involved) and a left-sided hemiparesis. Which of the following best localizes the lesion?","options":[{"label":"A","text":"A lesion affecting the right facial nucleus and the right corticospinal tract in the medulla."},{"label":"B","text":"A lesion affecting the right facial nucleus and the right corticospinal tract in the pons."},{"label":"C","text":"A lesion affecting the right facial nucleus and the left corticospinal tract in the pons."},{"label":"D","text":"A lesion affecting the right facial nucleus and the left corticospinal tract in the midbrain."},{"label":"E","text":"A lesion affecting the right internal capsule and the right facial nerve."}],"answer":"B","rationale":"The pons houses both the facial nucleus (causing ipsilateral LMN facial weakness) and corticospinal fibers (causing contralateral hemiparesis).","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-12","set_id":"compiled-part-5","type":"mcq","source_number":"12","source_page":16,"prompt":"An MRI report indicates an acute infarct in the paramedian midbrain. On a physical exam, which of the following findings would you NOT expect to see?","options":[{"label":"A","text":"Contralateral hemiparesis"},{"label":"B","text":"Ipsilateral loss of proprioception"},{"label":"C","text":"Ipsilateral pupillary dilation"},{"label":"D","text":"Contralateral intention tremor"},{"label":"E","text":"Ipsilateral ptosis"}],"answer":"B","rationale":"Paramedian midbrain infarcts cause contralateral hemiparesis and CN III palsy (Weber syndrome). The medial lemniscus (proprioception) is spared here, so ipsilateral proprioception loss wouldn’t occur.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-13","set_id":"compiled-part-5","type":"mcq","source_number":"13","source_page":16,"prompt":"YP has a left-sided oculomotor nerve (CN III) palsy and reveals a coarse tremor in the right arm and leg. This combination is most indicative of a stroke in the territory of which artery?","options":[{"label":"A","text":"Left Superior Cerebellar Artery (SCA)"},{"label":"B","text":"Right Posterior Cerebral Artery (PCA)"},{"label":"C","text":"Left Anterior Inferior Cerebellar Artery (AICA)"},{"label":"D","text":"Right Pontine Perforating Artery"},{"label":"E","text":"Left Posterior Inferior Cerebellar Artery (PICA)"}],"answer":"E","rationale":"Oculomotor palsy with contralateral tremor (Benedikt’s syndrome) is due to midbrain tegmentum lesion involving red nucleus and CN III, commonly in PICA territory.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-14","set_id":"compiled-part-5","type":"mcq","source_number":"14","source_page":16,"prompt":"Which cell is the primary, and only, output neuron of the cerebellar cortex? It sends inhibitory projections to the deep cerebellar nuclei.","options":[{"label":"A","text":"Granule Cell"},{"label":"B","text":"Basket Cell"},{"label":"C","text":"Purkinje Cell"},{"label":"D","text":"Golgi Cell"}],"answer":"C","rationale":"Purkinje cells are the sole output neurons of the cerebellar cortex. They send inhibitory (GABAergic) signals to the deep cerebellar nuclei.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-15","set_id":"compiled-part-5","type":"mcq","source_number":"15","source_page":17,"prompt":"Which layer of the cerebellar cortex contains the cell bodies of Purkinje cells?","options":[{"label":"A","text":"Molecular Layer"},{"label":"B","text":"Purkinje Layer"},{"label":"C","text":"Granular Layer"},{"label":"D","text":"White Matter"}],"answer":"B","rationale":"The Purkinje cell bodies form a distinct middle layer of the cerebellar cortex, between the molecular (superficial) and granular (deep) layers.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-16","set_id":"compiled-part-5","type":"mcq","source_number":"16","source_page":17,"prompt":"What is the name of the smallest and most numerous neurons in the brain, which are found in the granular layer of the cerebellum?","options":[{"label":"A","text":"Purkinje Cells"},{"label":"B","text":"Stellate Cells"},{"label":"C","text":"Golgi Cells"},{"label":"D","text":"Granule Cells"}],"answer":"D","rationale":"Granule cells are the smallest and most numerous neurons in the brain, located in the granular layer of the cerebellar cortex.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-17","set_id":"compiled-part-5","type":"mcq","source_number":"17","source_page":17,"prompt":"Which fiber input system carries information from the spinal cord, brainstem, and cerebral cortex to the cerebellum and synapses on granule cells?","options":[{"label":"A","text":"Climbing Fibers"},{"label":"B","text":"Mossy Fibers"},{"label":"C","text":"Parallel Fibers"},{"label":"D","text":"Purkinje Axons"}],"answer":"B","rationale":"Mossy fibers carry input from spinal cord, brainstem, and cortex to the cerebellum, synapsing on granule cells. They influence motor coordination indirectly.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-18","set_id":"compiled-part-5","type":"mcq","source_number":"18","source_page":17,"prompt":"What are the axons of granule cells called? They travel into the molecular layer and run parallel to the surface, synapsing on many Purkinje cells.","options":[{"label":"A","text":"Mossy Fibers"},{"label":"B","text":"Climbing Fibers"},{"label":"C","text":"Parallel Fibers"},{"label":"D","text":"Basket Fibers"}],"answer":"C","rationale":"The axons of granule cells ascend into the molecular layer, bifurcate, and run parallel to the surface — hence “parallel fibers.” They synapse with many Purkinje dendrites.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-19","set_id":"compiled-part-5","type":"mcq","source_number":"19","source_page":18,"prompt":"Which type of cerebellar interneuron is located in the molecular layer and provides lateral inhibition to Purkinje cells?","options":[{"label":"A","text":"Granule Cells"},{"label":"B","text":"Golgi Cells"},{"label":"C","text":"Stellate Cells"},{"label":"D","text":"Mossy Fibers"}],"answer":"C","rationale":"Stellate cells are inhibitory interneurons in the molecular layer, providing lateral inhibition to Purkinje cells to fine-tune cerebellar output.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-20","set_id":"compiled-part-5","type":"mcq","source_number":"20","source_page":18,"prompt":"A patient presents with a drooping eyelid (ptosis), an eye that is turned down and out, and a dilated pupil. Which cranial nerve is most likely impaired?","options":[{"label":"A","text":"Trochlear (CN IV)"},{"label":"B","text":"Abducens (CN VI)"},{"label":"C","text":"Oculomotor (CN III)"},{"label":"D","text":"Optic (CN II)"}],"answer":"C","rationale":"The oculomotor nerve controls most extraocular muscles and levator palpebrae (eyelid). Lesion → ptosis, “down and out” eye, and mydriasis.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-21","set_id":"compiled-part-5","type":"mcq","source_number":"21","source_page":18,"prompt":"Which cranial nerve is responsible for transmitting olfactory information (sense of smell) to the brain?","options":[{"label":"A","text":"Trigeminal (CN V)"},{"label":"B","text":"Facial (CN VII)"},{"label":"C","text":"Olfactory (CN I)"},{"label":"D","text":"Glossopharyngeal (CN IX)"}],"answer":"C","rationale":"The olfactory nerve is purely sensory, responsible for the sense of smell, and the only CN that does not synapse in the thalamus before reaching the cortex.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-22","set_id":"compiled-part-5","type":"mcq","source_number":"22","source_page":18,"prompt":"A patient has lost the sense of taste on the anterior two-thirds of their tongue. Their facial muscles and salivary gland function are normal. Which cranial nerve is specifically affected?","options":[{"label":"A","text":"The anterior root of the Trigeminal nerve (CN V)"},{"label":"B","text":"The Chorda Tympani branch of the Facial nerve (CN VII)"},{"label":"C","text":"The Lingual branch of the Glossopharyngeal nerve (CN IX)"},{"label":"D","text":"The Hypoglossal nerve (CN XII)"}],"answer":"B","rationale":"The chorda tympani carries taste fibers from the anterior two-thirds of the tongue. Motor and salivary branches are unaffected here.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-23","set_id":"compiled-part-5","type":"mcq","source_number":"23","source_page":19,"prompt":"During a routine exam, you ask a patient to shrug their shoulders against resistance and turn their head to the left. They are weak in both actions on the right side. This finding implicates a lesion of:","options":[{"label":"A","text":"The right Accessory nerve (CN XI)"},{"label":"B","text":"The left Accessory nerve (CN XI)"},{"label":"C","text":"The right Vagus nerve (CN X)"},{"label":"D","text":"The left Hypoglossal nerve (CN XII)"}],"answer":"A","rationale":"The spinal accessory nerve innervates sternocleidomastoid and trapezius. Weakness in turning head left and shrugging right shoulder = right CN XI lesion.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-24","set_id":"compiled-part-5","type":"mcq","source_number":"24","source_page":19,"prompt":"A patient has a hoarse voice, difficulty swallowing (dysphagia), and an absent gag reflex on the left side. The uvula deviates to the right when the patient says \"ahh.\" Which cranial nerve is most likely involved?","options":[{"label":"A","text":"Right Glossopharyngeal (CN IX)"},{"label":"B","text":"Left Glossopharyngeal (CN IX)"},{"label":"C","text":"Right Vagus (CN X)"},{"label":"D","text":"Left Vagus (CN X)"}],"answer":"D","rationale":"Lesion of the left vagus nerve causes hoarseness (laryngeal paralysis), dysphagia, absent gag reflex, and uvula deviation to the opposite (right) side.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-25","set_id":"compiled-part-5","type":"mcq","source_number":"25","source_page":19,"prompt":"Which of the following is a purely motor nerve that controls tongue movement?","options":[{"label":"A","text":"Facial (CN VII)"},{"label":"B","text":"Vestibulocochlear (CN VIII)"},{"label":"C","text":"Hypoglossal (CN XII)"},{"label":"D","text":"Trigeminal (CN V)"}],"answer":"C","rationale":"The hypoglossal nerve is purely motor, innervating intrinsic and extrinsic tongue muscles. Lesions cause tongue deviation toward the affected side.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-26","set_id":"compiled-part-5","type":"mcq","source_number":"26","source_page":20,"prompt":"A patient comes in after a minor head injury complaining of double vision that is worse when looking down and to the right, such as when walking down stairs. Which cranial nerve is most likely injured?","options":[{"label":"A","text":"The right Oculomotor nerve (CN III)"},{"label":"B","text":"The left Oculomotor nerve (CN III)"},{"label":"C","text":"The right Trochlear nerve (CN IV)"},{"label":"D","text":"The left Trochlear nerve (CN IV)"}],"answer":"C","rationale":"The trochlear nerve (CN IV) innervates the superior oblique muscle, which depresses and intorts the eye, especially when looking down and inward (as when descending stairs). Damage results in vertical diplopia that worsens when looking down and toward the opposite side. Because the trochlear nerve innervates the ipsilateral eye, injury to the right CN IV causes diplopia when looking down and to the right.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-27","set_id":"compiled-part-5","type":"mcq","source_number":"27","source_page":20,"prompt":"A patient has a complete loss of hearing in their right ear. Which cranial nerve is affected?","options":[{"label":"A","text":"The right Vestibular component of CN VIII"},{"label":"B","text":"The right Cochlear component of CN VIII"},{"label":"C","text":"The right Facial nerve (CN VII)"},{"label":"D","text":"The right Trigeminal nerve (CN V)"}],"answer":"B","rationale":"The cochlear division of the vestibulocochlear nerve (CN VIII) transmits auditory signals from the cochlea to the brainstem. Lesions here cause ipsilateral hearing loss. The vestibular portion instead carries information about balance and spatial orientation.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-28","set_id":"compiled-part-5","type":"mcq","source_number":"28","source_page":20,"prompt":"A 55-year-old man is brought to the clinic by his family. They have noticed he has become increasingly clumsy over the past year. On examination, you observe that his movements are jerky and uncoordinated. When he attempts to touch his finger and then his own nose, his hand overshoots the target (dysmetria). His gait is wide-based and unsteady, and he sways when standing with his feet together. When you tap his patellar tendon, his leg continues to oscillate up and down before settling. These clinical findings are most consistent with a lesion affecting which of the following neural structures?","options":[{"label":"A","text":"The substantia nigra of the midbrain"},{"label":"B","text":"The medial lemniscus in the brainstem"},{"label":"C","text":"The lateral corticospinal tract in the spinal cord"},{"label":"D","text":"The vestibulocerebellum (flocculonodular lobe)"},{"label":"E","text":"The cerebrocerebellum (lateral hemispheres)"}],"answer":"E","rationale":"The cerebrocerebellum (lateral hemispheres) coordinates skilled, precise voluntary movements and motor planning. Lesions here cause ataxia, dysmetria, intention tremor, and hypotonia — all of which match this case. The vestibulocerebellum affects balance and eye movements, not limb coordination.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-29","set_id":"compiled-part-5","type":"mcq","source_number":"29","source_page":21,"prompt":"The cerebellum is BEST known for its role in which of the following functions?","options":[{"label":"A","text":"Initiating voluntary muscle contractions"},{"label":"B","text":"Regulating heart rate and breathing"},{"label":"C","text":"Coordinating smooth and balanced movements"},{"label":"D","text":"Processing conscious thought and memory"}],"answer":"C","rationale":"The cerebellum fine-tunes motor activity by coordinating the timing, precision, and accuracy of movements, ensuring they are smooth, balanced, and well-controlled. It does not initiate movement — that’s the motor cortex’s role.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-30","set_id":"compiled-part-5","type":"mcq","source_number":"30","source_page":21,"prompt":"A patient's knee-jerk reflex when tested with a reflex hammer is unusually sluggish and their leg continues to swing back and forth several times. This change in reflex is most likely due to a problem with the:","options":[{"label":"A","text":"Spinal cord"},{"label":"B","text":"Cerebellum"},{"label":"C","text":"Frontal lobe"},{"label":"D","text":"Thalamus"}],"answer":"B","rationale":"A pendular reflex (continued swinging of the limb) indicates cerebellar hypotonia, a loss of the normal muscle tone regulation provided by the cerebellum. It’s not caused by spinal or cortical lesions.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-31","set_id":"compiled-part-5","type":"mcq","source_number":"31","source_page":21,"prompt":"During a neurological exam, a patient is asked to rapidly alternate touching their nose and then the examiner's finger. The patient's movements are slow, irregular, and clumsy. This deficit is called:","options":[{"label":"A","text":"Dysdiadochokinesia"},{"label":"B","text":"Hemiballismus"},{"label":"C","text":"Dysmetria"},{"label":"D","text":"Akinesia"}],"answer":"A","rationale":"Dysdiadochokinesia is the inability to perform rapid alternating movements, such as pronation–supination. It’s a hallmark of cerebellar dysfunction, particularly involving the lateral hemispheres.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-32","set_id":"compiled-part-5","type":"mcq","source_number":"32","source_page":22,"prompt":"If a person has a stroke affecting the RIGHT side of their cerebellum, which side of their body will most likely show signs of clumsiness and uncoordinated movement?","options":[{"label":"A","text":"The right side"},{"label":"B","text":"The left side"},{"label":"C","text":"Both sides equally"},{"label":"D","text":"Neither side"}],"answer":"A","rationale":"Cerebellar output pathways double-cross (decussate twice), resulting in ipsilateral motor control. Thus, right cerebellar lesions cause right-sided ataxia and dysmetria.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-33","set_id":"compiled-part-5","type":"mcq","source_number":"33","source_page":22,"prompt":"Which of the following is a direct result of the cerebellum's role in controlling muscle tone?","options":[{"label":"A","text":"It ensures muscles have the correct baseline level of tension to maintain posture."},{"label":"B","text":"It sends the initial command to a muscle to contract."},{"label":"C","text":"It provides the conscious sensation of a muscle being stretched."},{"label":"D","text":"It directly inhibits unwanted movements from the motor cortex."}],"answer":"A","rationale":"The cerebellum regulates muscle tone and posture through feedback to gamma motor neurons, ensuring proper baseline tension for maintaining postural stability and readiness for movement.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-34","set_id":"compiled-part-5","type":"mcq","source_number":"34","source_page":22,"prompt":"Which of the following is a hallmark sign of an Upper Motor Neuron (UMN) lesion?","options":[{"label":"A","text":"Fasciculations"},{"label":"B","text":"Muscle flaccidity"},{"label":"C","text":"Hyperreflexia"},{"label":"D","text":"Significant muscle atrophy"}],"answer":"C","rationale":"UMN lesions remove inhibitory cortical input on spinal reflex arcs, leading to hyperreflexia, spasticity, and a positive Babinski sign. Atrophy is minimal compared to LMN lesions.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-35","set_id":"compiled-part-5","type":"mcq","source_number":"35","source_page":22,"prompt":"A patient presents with weakness, muscle wasting, and fasciculations in the right hand. The Babinski sign is absent. This clinical picture is most consistent with:","options":[{"label":"A","text":"A stroke in the left motor cortex"},{"label":"B","text":"A spinal cord injury at C5"},{"label":"C","text":"A lesion of the median nerve"},{"label":"D","text":"A tumor pressing on the precentral gyrus"}],"answer":"C","rationale":"Fasciculations, atrophy, and flaccidity indicate a lower motor neuron lesion, not a cortical one. Localized findings in the right hand point to a peripheral nerve lesion — here, the median nerve.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-36","set_id":"compiled-part-5","type":"mcq","source_number":"36","source_page":23,"prompt":"The presence of a Babinski sign (extensor plantar response) is a definitive indicator of:","options":[{"label":"A","text":"A lower motor neuron lesion anywhere in the nervous system"},{"label":"B","text":"An upper motor neuron lesion above the level of the S1 spinal segment"},{"label":"C","text":"Damage to the dorsal root ganglion"},{"label":"D","text":"A peripheral neuropathy"}],"answer":"B","rationale":"A Babinski sign — dorsiflexion of the big toe and fanning of others — signifies corticospinal tract (UMN) damage. It reflects loss of descending inhibition over spinal reflexes.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-37","set_id":"compiled-part-5","type":"mcq","source_number":"37","source_page":23,"prompt":"Which combination of findings is uniquely characteristic of a Lower Motor Neuron (LMN) lesion?","options":[{"label":"A","text":"Spastic paralysis, mild disuse atrophy, hyperreflexia"},{"label":"B","text":"Flaccid paralysis, severe neurogenic atrophy, areflexia"},{"label":"C","text":"Hemiplegia, spasticity, a positive Babinski sign"},{"label":"D","text":"Hypertonia, clonus, absent superficial abdominal reflexes"}],"answer":"B","rationale":"LMN lesions cause flaccid paralysis, fasciculations, areflexia, and severe atrophy due to denervation. In contrast, UMN lesions produce spasticity and hyperreflexia.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-38","set_id":"compiled-part-5","type":"mcq","source_number":"38","source_page":23,"prompt":"A patient has weakness in the right lower extremity. The muscle tone is increased, and the deep tendon reflexes are ++ (brisk with clonus). Where is the most likely location of the lesion?","options":[{"label":"A","text":"Right sciatic nerve"},{"label":"B","text":"Left frontal motor cortex"},{"label":"C","text":"Right lumbar plexus"},{"label":"D","text":"Neuromuscular junction"}],"answer":"B","rationale":"UMN lesions above the decussation of the corticospinal tract (in the contralateral motor cortex) cause spastic weakness on the opposite side of the body.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-39","set_id":"compiled-part-5","type":"mcq","source_number":"39","source_page":23,"prompt":"Which sign is common to both severe UMN and LMN lesions?","options":[{"label":"A","text":"Spasticity"},{"label":"B","text":"Muscle hypertonia"},{"label":"C","text":"Muscle weakness"},{"label":"D","text":"Fasciculations"}],"answer":"C","rationale":"Both types of motor neuron lesions result in weakness, though the mechanisms differ (disuse vs. denervation). Other signs distinguish them (spasticity = UMN, flaccidity = LMN).","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-40","set_id":"compiled-part-5","type":"mcq","source_number":"40","source_page":24,"prompt":"A patient with a known history of diabetes presents with decreased sensation and weakness in a \"stocking-glove\" distribution. The weakness is accompanied by reduced reflexes and muscle wasting. This pattern suggests:","options":[{"label":"A","text":"An upper motor neuron lesion from a spinal cord tumor"},{"label":"B","text":"A single lower motor neuron lesion from a herniated disc"},{"label":"C","text":"A diffuse lower motor neuron problem from a peripheral neuropathy"},{"label":"D","text":"An upper motor neuron lesion from a brainstem stroke"}],"answer":"C","rationale":"A symmetric distal (“stocking-glove”) pattern with sensory loss, weakness, and areflexia is classic for peripheral neuropathy, commonly seen in diabetes mellitus.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-41","set_id":"compiled-part-5","type":"mcq","source_number":"41","source_page":24,"prompt":"A patient has a stroke that damages the medial portion of their medulla. This would most likely affect which major motor tract, causing weakness on the opposite side of the body?","options":[{"label":"A","text":"Corticospinal tract"},{"label":"B","text":"Medial lemniscus"},{"label":"C","text":"Spinothalamic tract"},{"label":"D","text":"Vestibulocochlear tract"}],"answer":"A","rationale":"The medial medulla contains the pyramids (corticospinal fibers). Lesions cause contralateral hemiparesis due to crossing of motor fibers in the pyramidal decussation.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-42","set_id":"compiled-part-5","type":"mcq","source_number":"42","source_page":24,"prompt":"Which cranial nerve is responsible for lateral eye movement and has its nucleus located in the pons?","options":[{"label":"A","text":"Oculomotor (CN III)"},{"label":"B","text":"Abducens (CN VI)"},{"label":"C","text":"Trigeminal (CN V)"},{"label":"D","text":"Abducens (CN VI)"}],"answer":"B","rationale":"The abducens nerve (CN VI) controls the lateral rectus muscle and originates from the abducens nucleus in the dorsal pons, near the floor of the fourth ventricle.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-43","set_id":"compiled-part-5","type":"mcq","source_number":"43","source_page":24,"prompt":"The loss of pain and temperature sensation on the opposite side of the body is a classic sign of damage to which tract as it travels through the brainstem?","options":[{"label":"A","text":"Corticospinal tract"},{"label":"B","text":"Medial lemniscus"},{"label":"C","text":"Spinothalamic tract"},{"label":"D","text":"Trigeminothalamic tract"}],"answer":"C","rationale":"The spinothalamic tract transmits pain and temperature sensations. Because it crosses early in the spinal cord, brainstem lesions produce contralateral sensory loss.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-44","set_id":"compiled-part-5","type":"mcq","source_number":"44","source_page":25,"prompt":"Which major artery supplies most of the lateral surface of the cerebral hemisphere, including the primary motor and sensory cortices?","options":[{"label":"A","text":"Anterior Cerebral Artery (ACA)"},{"label":"B","text":"Middle Cerebral Artery (MCA)"},{"label":"C","text":"Posterior Cerebral Artery (PCA)"},{"label":"D","text":"Basilar Artery"}],"answer":"B","rationale":"The MCA supplies the lateral surface of the frontal and parietal lobes, covering motor and sensory areas for the face and upper limb.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-45","set_id":"compiled-part-5","type":"mcq","source_number":"45","source_page":25,"prompt":"A patient presents with a right-sided lower motor neuron facial droop (forehead affected), loss of taste on the anterior two-thirds of the tongue, and hyperacusis. Which cranial nerve is affected, and in which part of the nerve?","options":[{"label":"A","text":"Trigeminal (CN V); Pons"},{"label":"B","text":"Facial (CN VII); Pons"},{"label":"C","text":"Glossopharyngeal (CN IX); Medulla"},{"label":"D","text":"Vagus (CN X); Medulla"}],"answer":"B","rationale":"All these functions — facial muscles, taste, stapedius control — belong to CN VII, whose nucleus lies in the pons. LMN lesion → ipsilateral paralysis including forehead.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-46","set_id":"compiled-part-5","type":"mcq","source_number":"46","source_page":25,"prompt":"A stroke in which of the following arteries would be most likely to cause a loss of vibratory sense and proprioception on the opposite side of the body?","options":[{"label":"A","text":"Anterior Inferior Cerebellar Artery (AICA)"},{"label":"B","text":"Paramedian branches of the Basilar Artery"},{"label":"C","text":"Posterior Inferior Cerebellar Artery (PICA)"},{"label":"D","text":"Middle Cerebral Artery (MCA)"}],"answer":"B","rationale":"The paramedian branches of the basilar artery supply the medial pons/medulla, including the medial lemniscus (vibration and proprioception pathway). Lesions cause contralateral sensory loss.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-47","set_id":"compiled-part-5","type":"mcq","source_number":"47","source_page":25,"prompt":"Which cranial nerve exits from the dorsal aspect of the brainstem and is the only one to do so?","options":[{"label":"A","text":"Oculomotor (CN III)"},{"label":"B","text":"Trochlear (CN IV)"},{"label":"C","text":"Abducens (CN VI)"},{"label":"D","text":"Hypoglossal (CN XII)"}],"answer":"B","rationale":"The trochlear nerve is unique — it exits dorsally from the midbrain and decussates, so it innervates the contralateral superior oblique muscle.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-48","set_id":"compiled-part-5","type":"mcq","source_number":"48","source_page":26,"prompt":"The \"water under the bridge\" analogy refers to the relationship between the uterine artery and the ureter. In neuroanatomy, a similar relationship exists in the caudal pons between trigeminal nerve fascicles and a nearby structure. Which nerve fascicle is vulnerable as it passes near the facial nucleus?","options":[{"label":"A","text":"The Abducens nerve (CN VI) fascicle"},{"label":"B","text":"The Trigeminal nerve (CN V) fascicle"},{"label":"C","text":"The Facial nerve (CN VII) fascicle"},{"label":"D","text":"The Glossopharyngeal nerve (CN IX) fascicle"}],"answer":"A","rationale":"In the caudal pons, the facial fibers loop around the abducens nucleus, forming the facial colliculus. Thus, the abducens fascicle (“bridge”) lies beneath the facial fibers (“water”), making it vulnerable in pontine lesions.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-49","set_id":"compiled-part-5","type":"mcq","source_number":"49","source_page":26,"prompt":"A patient has a tumor that is compressing the superior colliculi. Which primary function is most likely to be affected?","options":[{"label":"A","text":"Hearing"},{"label":"B","text":"Visual reflexes"},{"label":"C","text":"Balance and coordination"},{"label":"D","text":"Consciousness"}],"answer":"B","rationale":"The superior colliculi in the midbrain mediate visual tracking and reflexive eye movements, while the inferior colliculi process auditory input.","key_status":"source","key_source":"Compiled HS202 MCQs"},{"id":"compiled-part-5-50","set_id":"compiled-part-5","type":"mcq","source_number":"50","source_page":26,"prompt":"Vital autonomic centers that control heart rate, blood pressure, and respiration are primarily located in which brainstem structure?","options":[{"label":"A","text":"Midbrain"},{"label":"B","text":"Pons"},{"label":"C","text":"Medulla oblongata"},{"label":"D","text":"Cerebellum"}],"answer":"C","rationale":"The medulla oblongata contains cardiac, vasomotor, and respiratory centers essential for autonomic control of life-sustaining functions. Differences Between Upper and Lower Motor Neuron Lesions Feature Upper Motor Neuron (UMN) Lesion Lower Motor Neuron (LMN) Lesion Location of Damage Motor cortex, internal capsule, corticospinal or corticobulbar tracts Anterior horn cell, cranial nerve nuclei, peripheral nerves Type of Paralysis Spastic paralysis Flaccid paralysis Muscle Tone Increased (hypertonia) Decreased or absent (hypotonia) Muscle Bulk Normal or slightly decreased (disuse atrophy) Severely decreased (neurogenic atrophy) Reflexes (Deep Tendon Reflexes) Hyperreflexia (exaggerated reflexes) Hyporeflexia or areflexia (diminished or absent reflexes) Superficial Reflexes (e.g., abdominal, cremasteric) Absent Absent Pathological Reflexes Present (e.g., Babinski, Hoffman sign positive) Absent Fasciculations (muscle twitching) Absent Present Clonus Present (sustained rhythmic contractions) Absent Muscle Strength Weakness, especially in anti-gravity muscles (flexors of upper limbs, extensors of lower limbs) Weakness or paralysis in muscles supplied by the affected motor neuron Distribution of Weakness Group of muscles (pyramidal pattern) Individual muscles (segmental pattern) Example Lesions Stroke, Multiple Sclerosis, Spinal Cord Injury Poliomyelitis, Peripheral Nerve Injury, Guillain-Barré Syndrome Rubrospinal tract, which arises from the red nucleus and controls limb flexors. Vestibulospinal tract, which facilitates extensor tone for balance and posture. Reticulospinal tract, which helps maintain posture and axial muscle tone. Sensory relay from the thalamus to the somatosensory cortex, part of the ascending pathway, not descending. 🧠 Comparison of Descending and Ascending Pathways Feature Descending Pathways (Motor Fibers) Ascending Pathways (Sensory Fibers) Direction of Impulse From the brain → spinal cord → effectors (muscles/glands) From the receptors → spinal cord → brain Main Function Transmit motor commands that control voluntary and involuntary movements Transmit sensory information such as touch, pain, temperature, proprioception Type of Neurons Involved Upper and lower motor neurons First-, second-, and third-order sensory neurons Origin Motor cortex or brainstem motor centers Peripheral sensory receptors (skin, muscles, joints, viscera) Destination Skeletal muscles (voluntary) or autonomic effectors (involuntary) Sensory cortex of cerebrum or cerebellum Examples of Major Tracts - Pyramidal tracts: Corticospinal, Corticobulbar ● Extrapyramidal tracts: Rubrospinal, Reticulospinal, Vestibulospinal, Tectospinal | - Dorsal column tracts: Fasciculus gracilis & cuneatus (fine touch, proprioception) ● Spinothalamic tracts: Anterior (crude touch, pressure), Lateral (pain, temperature) ● Spinocerebellar tracts: Posterior & anterior (unconscious proprioception) | | Decussation (Crossing Over) | Usually in the medulla or spinal cord (e.g., pyramidal decussation) | Usually in the spinal cord or medulla, depending on tract | | Clinical Correlate | Lesions → Motor deficits (weakness, paralysis, hyperreflexia, spasticity) | Lesions → Sensory deficits (loss of sensation, numbness, paresthesia) | | Pathway Type | Efferent (away from CNS) | Afferent (toward CNS) |","key_status":"source","key_source":"Compiled HS202 MCQs"}]}],"recall_sets":[{"id":"structured-recall","group":"Recall","section":"Structured Recall","title":"Structured Recall","faculty":"Dr. Jaya","subtitle":"Sequence, matching, and clinical recall from the compiled file","source":"HSci202_Compiled_MCQs_with_Rationale.pdf","questions":[{"id":"structured-recall-1","set_id":"structured-recall","type":"recall","source_number":"Q11–Q15","source_page":11,"prompt":"Arrange the ascending pathway components in order until sensory information reaches the cortex.","answer":"Dorsal root ganglia → Primary sensory neurons → Dorsal columns/spinothalamic tracts → Brainstem nuclei → Thalamus","rationale":"Sensory input travels from receptors → dorsal root ganglia → spinal cord tracts → brainstem → thalamus → cortex."},{"id":"structured-recall-2","set_id":"structured-recall","type":"recall","source_number":"Q16","source_page":11,"prompt":"Which spinal pathway carries deep, chronic pain?","answer":"Spinoreticular pathway","rationale":"Source matching item."},{"id":"structured-recall-3","set_id":"structured-recall","type":"recall","source_number":"Q17","source_page":11,"prompt":"Which pathway carries fine touch, vibration, and proprioception?","answer":"Dorsal column system","rationale":"Source matching item."},{"id":"structured-recall-4","set_id":"structured-recall","type":"recall","source_number":"Q18","source_page":11,"prompt":"Which pathway mediates reflex head turning?","answer":"Tectospinal tract","rationale":"Source matching item."},{"id":"structured-recall-5","set_id":"structured-recall","type":"recall","source_number":"Q19","source_page":11,"prompt":"Which pathway is associated with fine motor function?","answer":"Lateral corticospinal tract","rationale":"Source matching item."},{"id":"structured-recall-6","set_id":"structured-recall","type":"recall","source_number":"Q20","source_page":11,"prompt":"Which pathway is associated with gross and postural motor function?","answer":"Anterior corticospinal tract","rationale":"Source matching item."},{"id":"structured-recall-7","set_id":"structured-recall","type":"recall","source_number":"Clinical 1","source_page":12,"prompt":"A patient has sensory ataxia, loss of vibration and joint position sense, and worsens when the eyes are closed. Which ascending pathway is involved?","answer":"Dorsal column–medial lemniscus pathway (gracile and cuneate fasciculi).","rationale":"The case describes loss of proprioceptive input from a dorsal-column lesion."},{"id":"structured-recall-8","set_id":"structured-recall","type":"recall","source_number":"Clinical 2","source_page":12,"prompt":"What disease is suggested by stamping gait, sensory ataxia, and loss of vibration/joint sense in the clinical case?","answer":"Tabes dorsalis (neurosyphilis).","rationale":"This is the source answer in the clinical case."},{"id":"structured-recall-9","set_id":"structured-recall","type":"recall","source_number":"Clinical 3","source_page":12,"prompt":"What sign is elicited when the patient cannot maintain a steady position with the eyes closed?","answer":"Romberg’s sign.","rationale":"A positive Romberg sign indicates reliance on vision for balance."}]},{"id":"simple-recall","group":"Recall","section":"Simple Recall","title":"Simple Recall","faculty":"Compiled recall sheet","subtitle":"Direct prompt → reveal answer","source":"HSci202_Neuroanatomy_Recalls.pdf","questions":[{"id":"simple-recall-1","set_id":"simple-recall","type":"recall","source_number":"1","source_page":1,"prompt":"Part of the brain involved in programming.","answer":"Premotor cortex","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-2","set_id":"simple-recall","type":"recall","source_number":"2","source_page":1,"prompt":"Part of the brain involved in planning.","answer":"Supplemental Motor Cortex","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-3","set_id":"simple-recall","type":"recall","source_number":"3","source_page":1,"prompt":"What visual-field deficit is associated in the recall sheet with the primary visual cortex of the occipital lobe?","answer":"Contralateral homonymous hemianopsia with macular sparing","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-4","set_id":"simple-recall","type":"recall","source_number":"4","source_page":1,"prompt":"Saccular aneurysms may result in what hemorrhage?","answer":"Subarachnoid hemorrhage","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-5","set_id":"simple-recall","type":"recall","source_number":"5","source_page":1,"prompt":"What common aneurysm site is listed in the recall sheet?","answer":"Anterior Cerebral artery and Anterior Communicating artery","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-6","set_id":"simple-recall","type":"recall","source_number":"6","source_page":1,"prompt":"The anterior limb of the internal capsule and corpus callosum are supplied by which artery in the recall sheet?","answer":"Anterior Cerebral Artery","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-7","set_id":"simple-recall","type":"recall","source_number":"7","source_page":1,"prompt":"The lower-limb homunculus is supplied by which artery?","answer":"Anterior Cerebral artery","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-8","set_id":"simple-recall","type":"recall","source_number":"8","source_page":1,"prompt":"The upper limb, hand, and face homunculus is supplied by which artery?","answer":"Middle Cerebral Artery","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-9","set_id":"simple-recall","type":"recall","source_number":"9","source_page":1,"prompt":"Which hemorrhage forms a biconvex lens-shaped appearance?","answer":"Epidural hemorrhage","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-10","set_id":"simple-recall","type":"recall","source_number":"10","source_page":1,"prompt":"What is the most common site of a berry aneurysm in the recall sheet?","answer":"Anterior communicating artery","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-11","set_id":"simple-recall","type":"recall","source_number":"13","source_page":1,"prompt":"How does the recall sheet contrast tension headache and migraine laterality?","answer":"Tension headache: bilateral; migraine: one side only","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-12","set_id":"simple-recall","type":"recall","source_number":"15","source_page":1,"prompt":"Loss of pain and temperature points to which tract?","answer":"Spinothalamic Tract","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-13","set_id":"simple-recall","type":"recall","source_number":"16","source_page":1,"prompt":"Which artery is emphasized for lateral medullary syndrome in the recall sheet?","answer":"PICA (Posterior Inferior Cerebellar Artery)","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-14","set_id":"simple-recall","type":"recall","source_number":"17","source_page":1,"prompt":"What descending tracts are remembered by RTR-V?","answer":"Reticulospinal, tectospinal, Rubrospinal, vestibulospinal","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-15","set_id":"simple-recall","type":"recall","source_number":"18","source_page":1,"prompt":"Which cortical areas are listed for eye, ear, and mouth?","answer":"Eye: 17, 18, 19; Ear: 41, 42; Mouth: 4, 6, 22","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-16","set_id":"simple-recall","type":"recall","source_number":"19","source_page":1,"prompt":"What sensory/motor pattern is listed for Brown-Séquard syndrome?","answer":"Ipsilateral motor loss; contralateral pain/temperature loss","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-17","set_id":"simple-recall","type":"recall","source_number":"21","source_page":1,"prompt":"What embryologic origin is listed for pancreatic beta cells?","answer":"Endoderm","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-18","set_id":"simple-recall","type":"recall","source_number":"22","source_page":1,"prompt":"What answer is linked to the keyword “ATROPINE” in the recall sheet?","answer":"SA node","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-19","set_id":"simple-recall","type":"recall","source_number":"23","source_page":1,"prompt":"In the syringomyelia mnemonic, which sensory term should you look for?","answer":"Pain","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."},{"id":"simple-recall-20","set_id":"simple-recall","type":"recall","source_number":"26","source_page":1,"prompt":"For the recall cue “Liver / cells / beta blockers,” which receptors are listed?","answer":"Alpha 1, Beta 2","rationale":"Answer preserved from the uploaded Neuroanatomy Recalls sheet."}]}],"reminders":["Review sympathetic vs parasympathetic responses (e.g., vasodilation and vasoconstriction).","Study the Waxman review questions.","Review generalized seizure.","Review what beta blockers are used for.","Study the types of spina bifida.","Review the types of headache."]};